import traceback

def parse(v):
    return int(v)

def load(rows):
    try:
        return [parse(r) for r in rows]
    except ValueError as e:
        raise RuntimeError("bad row") from e

try:
    load(["1", "x"])
except RuntimeError as e:
    print(e, "<-", type(e.__cause__).__name__)
    print(e.__cause__)
    print(traceback.extract_tb(e.__cause__.__traceback__)[-1].name)

import cProfile, pstats

def slow(n):
    return sum(i * i for i in range(n))

def job():
    for _ in range(3):
        slow(1000)

pr = cProfile.Profile()
pr.enable()
job()
pr.disable()
st = pstats.Stats(pr)
counts = {name: nc for (f, line, name), (cc, nc, *_rest) in st.stats.items()
          if name in ("slow", "job")}
print(sorted(counts.items()))

